entries[57755] = { ["name"] = "Heldenhafter Wurf", ["text"] = "8 - 30 Meter Reichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nSchutz ( Schutzkrieger )\nWirft Eure Waffe nach dem Gegner und fügt ihm (35% der Angriffskraft) körperlichen Schaden zu. Erzeugt ein hohes Maß an Bedrohung.\n\nWaffen, Furor\nWirft Eure Waffe nach dem Gegner und fügt ihm (35% der Angriffskraft) körperlichen Schaden zu. Erzeugt ein hohes Maß an Bedrohung." }
entries[57757] = { ["name"] = "Feuerregen", ["text"] = "40 Meter Reichweite\nSofort\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 6 Sek. lang alle 2 Sek. 560 Feuerschaden zufügt." }
